    bench_patches = image_patch.find("bench")

    if not man_patches or not bench_patches:
        return image_patch

    sitting_man_patches = []

    for man_patch in man_patches:
        for bench_patch in bench_patches:
            if is_on(bench_patch, man_patch):
                sitting_man_patches.append(man_patch)

    return sitting_man_patches[0]

def is_on(bench: ImagePatch, obj: ImagePatch) -> bool:
    obj_top = obj.upper
    bench_bottom = bench.lower
    return obj_top <= bench_bottom

